import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2 = x
    return (x1**2 + x2**2 + x1*x2 + 0.5*x1 + 0.3*x2 + 0.1*x1**3)

import numpy as np

def problem(x: np.ndarray) -> float:
    x = np.asarray(x)
    assert x.ndim == 1 and x.shape[0] == 2

    return np.sum(x**2) + 0.1 * np.exp(x[0]) + 0.05 * np.sin(5 * x[1])

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2 = x
    return (0.8*x1**2 + 0.6*x2**2 + 0.4*x1*x2 + 0.2*x1 + 0.1*x1**3)

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2 = x
    return float(0.5 * x1**2 + 0.1 * x1**3 + 0.7 * x2**2 + 0.5 * np.exp(-0.2 * np.max(np.abs(x))))
